const ok = errors.length === 0;
return [{ json: {
  ok, errors, error: errors.join('; '),
  output: page, critique: null, had_meta,
  keyword, domain, country: S(b.country).trim(), currency: '', page_type: pageType, page_role: 'standard', article_like: false,
