// unweighted share. No URL constructor (n8n sandbox), no defineProperty.
//   targets(keyword, pages, opts) -> { targets, partial, self, keyword_words, basis }
//     opts.skip   URLs never compared (the pages this run read and compares by text, the page being improved)
//     opts.self   URLs of this run's own page (the ladder's planned address); with opts.self_aware a page at one of them is this run's own
//                 page: listed in `self`, never a duplicate of itself
//     opts.slug_self  (before the brief only) a page whose last address segment is the keyword's own slug is the keyword's own page too:
//                 the run improves it (the verdict's existing page) rather than duplicating it. Not in the late check: there, an unread
//                 page at the keyword's own address IS the clearest duplicate (harness CTF5)
//     opts.ladder a page of a keyword ladder: a page that carries only PART of the keyword's weight is the ladder's planned neighbour
//                 (the rung links up to it), listed in `partial` as advice; only a page carrying all of it is a duplicate target
//     opts.max    targets kept (3)
const DUP = (() => {
  const S = (v) => String(v == null ? '' : v);
  const SHARE = 75, MAX = 3;
  // the tokenizer of SHG (_shingle.js), character for character, so the late check finds what it always found
  const norm = (t) => S(t)
    .replace(/```[\s\S]*?```/g, ' ')
    .replace(/!\[[^\]]*\]\([^)]*\)/g, ' ')
    .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
    .replace(/<[^>]*>/g, ' ')
    .replace(/https?:\/\/\S+|www\.\S+/g, ' ')
    .replace(/[‘’ʼ]/g, "'").replace(/[“”]/g, '"').replace(/[–—]/g, '-')
    .toLowerCase().replace(/[^a-z0-9'\s]+/g, ' ').replace(/\s+/g, ' ').trim();
  const words = (t) => { const s = norm(t); return s ? s.split(' ') : []; };
  const toks = (t) => new Set(words(t).filter(w => w.length > 2));
  const keyOf = (u) => S(u).toLowerCase().replace(/[#?].*$/, '').replace(/\/+$/, '');
  const pathKey = (u) => keyOf(u).replace(/^https?:\/\/[^\/]+/, '');
  const slugOf = (u) => { const p = pathKey(u).split('/').filter(Boolean); return p.length ? p[p.length - 1].replace(/\.[a-z]{2,5}$/, '') : ''; };
  const slugify = (k) => S(k).toLowerCase().replace(/[‘’ʼ']/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
  // the page's words: title + H1 + address (the address with its separators as spaces, exactly as the late check always read it)
  const pageToks = (p) => toks(S(p && p.title) + ' ' + S(p && p.h1) + ' ' + S(p && p.url).replace(/[-_/]+/g, ' '));
  const targets = (keyword, pages, opts) => {
    const o = opts || {};
    const kw = toks(keyword);
    const out = { targets: [], partial: [], self: [], keyword_words: kw.size, basis: '' };
    if (!kw.size) { out.basis = 'the keyword has no word of 3 letters or more to compare'; return out; }
    const list = (Array.isArray(pages) ? pages : []).filter(p => p && S(p.url));
    const sets = list.map(pageToks);
    // how many of the site's pages carry each keyword word: the rarer, the more it says about a page
    const N = sets.length;
    const w = {};
    for (const t of kw) { let df = 0; for (const s of sets) if (s.has(t)) df++; w[t] = Math.log((N + 1) / (df + 1)) + 1; }
    const total = [...kw].reduce((a, t) => a + w[t], 0);
    const skip = new Set([...(o.skip || [])].map(keyOf).filter(Boolean));
    const selfP = new Set([...(o.self || [])].map(pathKey).filter(Boolean));
    const kslug = slugify(keyword);
    const max = Number(o.max) > 0 ? Number(o.max) : MAX;
    for (let i = 0; i < list.length; i++) {
      const p = list[i]; const k = keyOf(p.url);
      if (!k || skip.has(k)) continue;
      const set = sets[i]; if (!set.size) continue;
      let hit = 0, hw = 0;
      for (const t of kw) if (set.has(t)) { hit++; hw += w[t]; }
      const plain = Math.round((hit / kw.size) * 100);
      const share = Math.round((hw / total) * 100);
      // both measures must reach the bar: the weighting only ever REMOVES a match the plain share made (a page that shares only the site's
      // common words), it never adds one the late check did not make before
      if (plain < SHARE || share < SHARE) continue;
      const row = { url: S(p.url), title: S(p.title), keyword_words_shared_pct: plain, weighted_pct: share };
      if (o.self_aware && ((selfP.size && selfP.has(pathKey(p.url))) || (o.slug_self && kslug && slugOf(p.url) === kslug))) { out.self.push(row); continue; }
      if (o.ladder && hit < kw.size) { out.partial.push(row); continue; }
      out.targets.push(row);
      if (out.targets.length >= max) break;
    }
    out.basis = 'the keyword\'s ' + kw.size + ' word(s) of 3+ letters against the title, main heading and address of ' + N + ' page(s) of the site, '
      + 'a page carrying ' + SHARE + '% or more of those words, and of their weight when each word counts by how few of the site\'s pages carry it, is aimed at the same search';
    return out;
  };
  return { targets, words, slugify, slugOf, SHARE, MAX };
})();
// Originality check (FIX_PLAN G5, 2026-10-13). Runs between *Content QA* and *Needs Revision?*, so a draft that repeats someone else's
// words -- or our own page's -- never reaches the customer: the quality check fails, the editor is sent in with the passage named, and the
// report says against which page and by how much.
// It compares the finished draft with the texts this run already fetched, so it costs nothing and calls nothing:
//   * the competitor pages the brief was written from (*Analyze Competitor Pages*, up to 9,000 characters each);
//   * the site's own pages this run read (*Collect Client Pages*: the existing page on the topic, the homepage, one related page -- the
//     inventory page that matches the keyword is read as the "existing" page, P2-5);
//   * the rest of the page inventory (D11 / SM.pages) by title and slug only -- no text of them is in hand, and fetching a whole site to
//     check one draft would cost more than it is worth. A near-identical target is reported as a duplicate target, not as overlap.
// Measure: the share of the draft's 8-word windows that a single page also carries (SHG). The page being improved is the exception: a
// rewrite is supposed to keep that page's text, so its overlap is reported and never counted as a failure.
const item = $input.first();
const d = item.json || {};
const qa = { ...(d.content_qa || {}) };
const warnings = Array.isArray(qa.warnings) ? [...qa.warnings] : [];

const S = (v) => String(v == null ? '' : v);
const bare = (u) => { const m = S(u).trim().match(/^https?:\/\/(?:[^@\/?#]*@)?([^\/?#:]+)/i); return m ? m[1].toLowerCase().replace(/^www\./, '') : ''; };
const keyOf = (u) => S(u).toLowerCase().replace(/[#?].*$/, '').replace(/\/+$/, '');
const THRESHOLD = (() => { const n = Number(d.originality_max_overlap_pct); return n > 0 && n <= 100 ? n : 15; })();

// ---- the draft, without the meta lines and the generated schema ----
const draftMd = S(d.output || d.page_markdown)
  .replace(/^(Title|Meta Description|Slug|Primary Keyword|Secondary Keywords|Production Brief):.*$/gim, '')
  .replace(/<script[\s\S]*?<\/script>/gi, '');
const draftShingles = SHG.shingles(draftMd);
const draftWords = SHG.words(draftMd).length;

// ---- the sources this run already has ----
const sources = [];
let competitors = [];
try { competitors = ($('Analyze Competitor Pages').first().json || {}).competitors || []; } catch (e) { competitors = []; }
if (!competitors.length && Array.isArray(d.competitors)) competitors = d.competitors;
const MIN_WORDS = 40;   // below this a page has no passage worth comparing; the 8-word window needs real sentences
for (const c of competitors) {
  const text = S(c && (c.content_full || c.content));
  if (text.split(/\s+/).filter(Boolean).length < MIN_WORDS) continue;
  sources.push({ kind: 'competitor', label: S(c.domain) || bare(c.url), url: S(c.url), rank: Number(c.rank) || null, text });
}
let clientPages = [];
try { clientPages = ($('Collect Client Pages').first().json || {}).client_pages || []; } catch (e) { clientPages = []; }
if (!clientPages.length && Array.isArray(d.client_pages)) clientPages = d.client_pages;
const improving = keyOf((d.existing_page && d.existing_page.url) || d.existing_page_url || '');
for (const p of clientPages) {
  const text = S(p && p.text);
  if (text.split(/\s+/).filter(Boolean).length < MIN_WORDS) continue;
  const isImproved = S(p.kind) === 'existing' || (!!improving && keyOf(p.url) === improving);
  sources.push({ kind: isImproved ? 'improved' : 'own', label: S(p.url) || S(p.kind), url: S(p.url), rank: null, text });
}

// ---- overlap per source ----
const sets = sources.map(s => SHG.setOf(s.text));
const commonSet = SHG.common(sets, 3);   // phrasing most of the pages use: reported, never counted as copying from one page
const measured = sources.map((s, i) => {
  const r = SHG.compare(draftShingles, null, { sourceSet: sets[i], passages: 2 });
  const commonHits = draftShingles.filter(sh => sets[i].has(sh) && commonSet.has(sh)).length;
  return { source: s.label, url: s.url, kind: s.kind, rank: s.rank, overlap_pct: r.overlap_pct, matched_windows: r.matched,
    common_windows: commonHits, longest_passage_words: r.longest_words, passages: r.passages };
}).sort((a, b) => b.overlap_pct - a.overlap_pct);

// ---- the rest of the inventory: a page aimed at the same search, checked by title and slug (no text of it in hand) ----
let MODEL = null;
try { MODEL = $('Site Model').first().json.site_model || null; } catch (e) {}
if (!MODEL && d.site_model && typeof d.site_model === 'object') MODEL = d.site_model;
// W0-D (page-quality 2026-10-29): the rule is the kit DUP (v5/code/_dup_targets.js), the one *Parse Verdict* now applies BEFORE the
// brief; this late check stays as the safety net. Two refinements, both only ever removing a match: a page that shares only the site's
// common words is not a duplicate (the weighted share), and the ladder's planned address for this very page is never its own duplicate.
const readKeys = new Set(sources.map(s => keyOf(s.url)).filter(Boolean));
const duplicate_targets = MODEL ? DUP.targets(d.keyword, SM.pages(MODEL), { skip: [...readKeys, improving], self: [d.ladder_target_url || ''], self_aware: true }).targets : [];

const worst = measured.filter(m => m.kind !== 'improved')[0] || null;
const failing = worst && worst.overlap_pct > THRESHOLD ? worst : null;
const improved = measured.find(m => m.kind === 'improved') || null;
const originality = {
  threshold_pct: THRESHOLD,
  window_words: SHG.N,
  draft_words: draftWords,
  draft_windows: draftShingles.length,
  pages_compared: measured.length,
  competitor_pages: sources.filter(s => s.kind === 'competitor').length,
  own_pages: sources.filter(s => s.kind !== 'competitor').length,
  inventory_pages_by_title: duplicate_targets.length,
  top_overlaps: measured.slice(0, 5),
  highest_pct: worst ? worst.overlap_pct : null,
  highest_source: worst ? worst.source : null,
  improved_page: improved ? { source: improved.source, overlap_pct: improved.overlap_pct } : null,
  duplicate_targets,
  passed: !failing,
  basis: measured.length
    ? 'the share of the draft\'s ' + SHG.N + '-word windows found on one page, measured against ' + measured.length + ' page(s) this run read ('
      + sources.filter(s => s.kind === 'competitor').length + ' competitor, ' + sources.filter(s => s.kind !== 'competitor').length + ' of this site)'
    : 'no page text was available in this run, so nothing could be compared'
};
if (!measured.length) originality.passed = null;   // unknown is not a pass: the report says it could not be checked

// ---- what the editor and the customer are told ----
if (failing) {
  const p = failing.passages[0];
  const who = failing.kind === 'competitor' ? 'the competitor page ' + failing.source : 'this site\'s own page ' + failing.source;
  warnings.push('Originality: ' + failing.overlap_pct + '% of this draft is word for word the same as ' + who
    + ' (limit ' + THRESHOLD + '%; longest identical run ' + failing.longest_passage_words + ' words'
    + (p ? ': "' + p.text + '"' : '') + '). Rewrite those passages in our own words and from our own angle'
    + (failing.kind === 'competitor' ? '; never reuse a competitor\'s sentences, lists or table rows.'
      : '; two pages of the same site with the same text compete with each other: either make this page clearly different or improve that page instead.'));
}
for (const m of measured.filter(x => x.kind !== 'improved' && x !== failing && x.overlap_pct > THRESHOLD * 0.67).slice(0, 2)) {
  warnings.push('Originality: ' + m.overlap_pct + '% of this draft also appears on ' + m.source + ' (under the ' + THRESHOLD + '% limit, worth a read before publishing)');
}
if (duplicate_targets.length) {
  warnings.push('This site already has a page aimed at the same search: ' + duplicate_targets.map(x => x.url).join(', ')
    + '. Improve that page instead of publishing a second one, or make clear in the brief how this page is different (its text could not be compared: it was not read in this run)');
}

qa.originality = originality;
qa.warnings = warnings;
// CT-FIX (review item 14): the next step said "Then publish it." beside the warning that the site already has a page for this search.
if (duplicate_targets.length && qa.quality && typeof qa.quality === 'object' && /Then publish it\./.test(String(qa.quality.next_step || ''))) {
  qa.quality = { ...qa.quality, next_step: String(qa.quality.next_step).replace('Then publish it.', 'Then, rather than publishing a second page for the same search, use it to improve ' + duplicate_targets[0].url + ' (or say in the brief how this page differs).') };
}
if (failing) {
  qa.passed = false;
  qa.passed_copy = false;
  qa.editor_needed = true;
  // B3-3 (2026-10-15, benchmark area 3): *Content QA* finalises the delivery gate -- `quality`, `not_ready`, `quality_label`,
  // `publishable`, the reasons -- and this node runs AFTER it, so flipping `passed` alone left every one of them saying the opposite.
  // Proven on the node code: a draft 100% identical to a competitor page, failing on the last round, came out of here with
  // `publishable: true`, `not_ready: false` and `quality.label: "passed the quality check"`. Those fields are what the Word file's
  // status line, the `-DRAFT` file name, the package's "DID NOT PASS" banner, meta.json, the callback and the app all read, so a
  // plagiarised page was delivered labelled as having passed. A gate that fails has to refuse; it must never only be a label.
  const roundsLeft = Math.max(0, Number(qa.rounds_left) || 0);
  const whose = failing.kind === 'competitor' ? 'the competitor page ' : 'this site\'s own page ';
  const reason = 'it repeats ' + failing.overlap_pct + '% of ' + whose + failing.source + ' word for word (the limit is ' + THRESHOLD + '%)';
  qa.publishable = false;
  qa.not_ready = !roundsLeft;
  qa.quality_label = roundsLeft ? 'needs another editing round before it can be published'
    : 'did not pass the quality check, so it is not ready to publish';
  qa.not_ready_reasons = !roundsLeft
    ? [reason, ...(Array.isArray(qa.not_ready_reasons) ? qa.not_ready_reasons : [])].filter((x, i, a) => x && a.indexOf(x) === i).slice(0, 6)
    : (Array.isArray(qa.not_ready_reasons) ? qa.not_ready_reasons : []);
  qa.quality = { ...(qa.quality && typeof qa.quality === 'object' ? qa.quality : {}),
    passed: false, publishable: false, not_ready: qa.not_ready, label: qa.quality_label, reasons: qa.not_ready_reasons,
    // 2026-10-21: what to do is an edit by hand, never a paid re-run (Content QA's next_step, with the repeated passages first)
    next_step: roundsLeft ? '' : 'Finish this draft by hand: rewrite the passages it repeats from ' + failing.source + ' in your own words' + ((qa.quality || {}).next_step ? ', and ' + String(qa.quality.next_step).replace(/^Finish this draft by hand:\s*/, '') : '. Then publish it. You do not need a new run for these edits: a new run writes a whole new page and is charged again.'),
    fix_by: roundsLeft ? '' : 'edit',
    note: roundsLeft ? '' : 'The editor had ' + (Number(qa.max_rounds) || 1) + ' round(s) and the page still repeats another page word for word: it is delivered as a draft to finish by hand, not as a page to publish as it is.' };
}
return [{ json: { ...d, content_qa: qa } }];

// ---- PF: the page pipeline's one contract, its one score and its fixes (H1, 2026-10-27; inlined through the PAGE_FIX marker) ----
// docs/content-quality-2026-10-27/R1_PIPELINE_ANALYSIS.md: the four production page runs (949, 2195, 2552, 2575) all came out "not ready
// to publish". One full-page Editor pass with no safety net made 3 of the 4 pages worse (two cut off, one regressed on keyword, coverage,
// claims and links), the Brief, the Copywriter, the Critic, the Editor and the quality check each held a different length / bracket /
// claim rule, every warning blocked, and the PDF printed the Critic's grade of the FIRST draft. R2_MARKET_RESEARCH.md: no leading tool
// blocks on SEO metrics; facts, trust and legal problems are what block. This kit is the one place those rules live:
//   PF.contract(prev)          the contract every writer prompt prints (length as a band, no brackets, the claim rule, page-type targets)
//   PF.split / PF.join         a page as its head (meta lines) + sections (s0 = H1 and introduction, s1.. = each H2); lossless
//   PF.fix(md, ctx)            the deterministic fixes, run before every quality check (no model, cannot invent anything)
//   PF.classify(qa, md, ctx)   BLOCKING (facts, trust, legal, a cut page) vs ADVISORY (length, coverage, structure, style)
//   PF.weakFigures / reviewed  W0-H (Fix 3b): a figure whose only source is weak, and the blind second read's problems, as soft blockers
//   PF.score / PF.better       ONE comparison for every candidate draft: hard blockers, then soft blockers, then advisory distance
//   PF.plan(md, cls, qa, ctx)  the section-targeted edit job: only the sections with a problem, each with its own problem list
//   PF.parseSections / merge   the editor's answer (one block per section) merged into the page, every other byte kept
//   PF.neutralize(md, cls)     the system's own neutral rewrite of whatever a fact would be needed for (delete / unlink / neutral CTA)
//   PF.deliver(...)            ready | ready_with_questions | not_ready, in plain customer words, with the client questions
//   PF.toc(md, ref)            the linked contents list kept, and following its headings, through the final version (fu-finalize-toc)
//   PF.fragment / ctaSentence / finalGuard   W05-C (2026-10-30): what is a sentence, what is an invitation to get in touch, and the final
//                              version repaired against the page it was made from (list markers, a spliced heading, a second invitation)
// Pure: no clock, no network, no n8n globals, no URL constructor, no Object.defineProperty, no structuredClone (n8n sandbox rules).
const PF = (() => {
  const S = (v) => String(v == null ? '' : v);
  const EDIT_MAX = 3;           // section-targeted editing rounds at most; the loop stops earlier as soon as a round improves nothing
  const META = /^(Title|Meta Description|Meta Title|Slug|Primary Keyword|Secondary Keywords)\s*:/i;
  const words = (t) => S(t).split(/\s+/).filter(Boolean).length;
  const plain = (s) => S(s).replace(/\[([^\[\]]+)\]\([^)]*\)/g, '$1').replace(/[*_`>#]+/g, '').replace(/\s+/g, ' ').trim();
  const escRe = (s) => S(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  // customer wording: no em / en dashes, curly quotes or the ellipsis character in anything this kit writes (owner rule, 2026-10-19)
  const clean = (s) => S(s).replace(/\s*[\u2014\u2013]\s*/g, ': ').replace(/[\u201C\u201D]/g, '"').replace(/[\u2018\u2019]/g, "'").replace(/\u2026/g, '...').replace(/:\s*:/g, ':').trim();
  const STOP = new Set('the a an and or of for to in on with by at from about this that these those your our its it is are be how what which why when who you we they their them than then into over under more most can will does do not but any all one two also very just only such been being has have had was were'.split(' '));
  const toks = (t) => S(t).toLowerCase().split(/[^\p{L}\p{N}&]+/u).filter(w => w.length > 2 && !STOP.has(w));
  const overlap = (a, b) => { const A = [...new Set(toks(a))]; if (!A.length) return 0; const B = new Set(toks(b)); return A.filter(w => B.has(w)).length / A.length; };
  const hostOf = (u) => { const m = S(u).match(/^https?:\/\/(?:[^@\/?#]*@)?([^\/?#:]+)/i); return m ? m[1].toLowerCase().replace(/^www\./, '') : ''; };
  const keyOf = (u) => S(u).trim().toLowerCase().replace(/^https?:\/\/(?:www\.)?/, '').replace(/[#?].*$/, '').replace(/\/+$/, '');
  const SMALL = new Set(['a', 'an', 'and', 'as', 'at', 'by', 'for', 'in', 'of', 'on', 'or', 'the', 'to', 'vs', 'with']);
  const titleCase = (k) => S(k).split(/\s+/).filter(Boolean).map((w, i) => i > 0 && SMALL.has(w.toLowerCase()) ? w.toLowerCase() : /^[a-z]{2,4}$/.test(w) && /^(erp|crm|ai|uae|ksa|gcc|vat|seo|sap|hr|it|b2b|saas|api|ms|iot|ml|pdf|faq)$/.test(w) ? w.toUpperCase() : w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
  const QUESTION_KW = /^(is|are|can|does|do|what|which|how|why|when|where|who|should|will)\b/i;

  // ---------- 1. the contract ----------
  const PT_TARGETS = {
    guide: { h2: [5, 9], text: '5 to 9 H2 sections, at least 3 headings phrased as the questions readers ask with a 40-60 word answer right under each, a comparison table where options are compared, the call to action last' },
    service: { h2: [4, 8], text: '4 to 8 H2 sections: what the service covers, who it suits, how to decide, how to start; at least 2 question headings; the call to action last' },
    local: { h2: [4, 7], text: '4 to 7 H2 sections; the address, phone and service area only as the business profile gives them; the call to action last' },
    case_study: { h2: [4, 7], text: 'challenge, approach, result and what the reader can learn, every fact from the case study on file; nothing added' },
    other: { h2: [4, 9], text: '4 to 9 H2 sections, at least 3 question headings answered directly, the call to action last' }
  };
  const kindOf = (pageType, role) => { const t = S(pageType).toLowerCase(); if (S(role) === 'local') return 'local'; if (S(role) === 'case_study' || /case stud/.test(t)) return 'case_study';
    if (/service|landing|product|solution/.test(t)) return 'service'; if (/guide|blog|article|pillar|hub|how/.test(t)) return 'guide'; return 'other'; };
  const bandOf = (p) => { const LB = ((p || {}).competitor_analysis || {}).length_band || (p || {}).length_band || null;
    return LB && (LB.ok || LB.source === 'page_type') && Number(LB.low) > 0 && Number(LB.high) >= Number(LB.low)
      ? { low: Number(LB.low), high: Number(LB.high), source: LB.ok ? 'ranking_pages' : 'page_type', basis: clean(LB.basis) } : null; };
  const contract = (prev) => {
    const p = prev || {};
    const band = bandOf(p);
    const kind = kindOf(p.page_type, p.page_role);
    const biz = S((p.site_profile || {}).business_name || (p.site_description || {}).business_name || p.business_name || 'the business').trim() || 'the business';
    const length_text = band
      ? 'LENGTH: judged as a band, ' + band.low + '-' + band.high + ' words of main content' + (band.basis ? ' (' + band.basis + ')' : '') + '. Anywhere inside the band is right: aim for the brief\'s target word count, never pad to reach a number and never cut a complete answer to hit one. Length is advice, never a reason to refuse the page.'
      : 'LENGTH: aim for the brief\'s target word count; the check accepts anything from 80% to 125% of it. Never pad and never cut a complete answer to hit a number. Length is advice, never a reason to refuse the page.';
    const rules = [
      'THE PAGE CONTRACT (the brief, the writer, the reviewer, the editor and the quality check all apply these same rules)',
